package com.trampolim.api.education;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.nio.file.*;
import java.io.*;
import org.junit.jupiter.api.*;
import org.flywaydb.core.Flyway;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.support.JdbcTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.apache.pdfbox.pdmodel.*;
import org.apache.pdfbox.pdmodel.font.*;
import org.apache.pdfbox.pdmodel.interactive.action.PDActionJavaScript;

class LibraryPostgresTest {
    static JdbcTemplate admin,jdbc;static String schema;LibraryService service;LearningAccess access;LearningController learning;TransactionTemplate tx;LibraryPdfStore store;Path directory;
    String teacherEmail,studentEmail,otherEmail;long teacher,student,other,course,subject,module,lesson,secondLesson;
    @BeforeAll static void database(){String url=env("CAPACITA_DB_URL","jdbc:postgresql://localhost:5434/trampolim_capacita_db");String user=env("CAPACITA_DB_USERNAME","trampolim_capacita"),password=env("CAPACITA_DB_PASSWORD","dev_capacita_only");admin=new JdbcTemplate(new DriverManagerDataSource(url,user,password));schema="library_test_"+UUID.randomUUID().toString().replace("-","");admin.execute("CREATE SCHEMA "+schema);var source=new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema,user,password);Flyway.configure().dataSource(source).locations("classpath:db/migration-capacita").load().migrate();jdbc=new JdbcTemplate(source);}
    @AfterAll static void cleanup(){if(admin!=null&&schema!=null)admin.execute("DROP SCHEMA "+schema+" CASCADE");}
    @BeforeEach void setup()throws Exception{teacherEmail=email();studentEmail=email();otherEmail=email();teacher=account(teacherEmail);student=account(studentEmail);other=account(otherEmail);jdbc.update("INSERT INTO learning_account_roles(user_id,role) VALUES (?,'TEACHER'),(?,'TEACHER')",teacher,other);access=new LearningAccess(jdbc);ReflectionTestUtils.setField(access,"bootstrapAdmins","");learning=new LearningController(jdbc,access);service=new LibraryService(jdbc,access,learning);tx=new TransactionTemplate(new JdbcTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));store=new LibraryPdfStore();directory=Files.createTempDirectory("library-private-test-");ReflectionTestUtils.setField(store,"root",directory.toString());course=((Number)learning.createCourse(teacherEmail,new LearningController.CourseInput("Library course","Test","Math",null,"PUBLISHED")).get("id")).longValue();subject=jdbc.queryForObject("INSERT INTO learning_subjects(course_id,title) VALUES (?,'Math') RETURNING id",Long.class,course);module=jdbc.queryForObject("INSERT INTO learning_modules(subject_id,title) VALUES (?,'Module') RETURNING id",Long.class,subject);lesson=lesson();secondLesson=lesson();}
    @AfterEach void files()throws Exception{try(var paths=Files.walk(directory)){for(Path path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    private long account(String email){return jdbc.queryForObject("INSERT INTO student_users(email,password_hash,full_name,education_stage,email_verified,account_status,terms_accepted_at) VALUES (?,'test-only','Library fixture','HIGH_SCHOOL',TRUE,'ACTIVE',CURRENT_TIMESTAMP) RETURNING id",Long.class,email);}
    private long lesson(){return jdbc.queryForObject("INSERT INTO learning_lessons(module_id,title,status,media_key,duration_seconds,validation_status) VALUES (?,'Test lesson','PUBLISHED',?,180,'READY') RETURNING id",Long.class,module,UUID.randomUUID());}
    private LibraryService.MaterialInput input(String status,boolean download,String scope,List<Long> lessons,Integer revision){return new LibraryService.MaterialInput(course,subject,module,"Frações e proporções","Apoio complementar","Frações","Apostila","Texto alternativo do professor",scope,download,status,lessons,revision);}
    private long create(){return ((Number)tx.execute(status->service.create(teacherEmail,input("DRAFT",true,"STUDENTS",List.of(lesson,secondLesson),null))).get("id")).longValue();}
    private int revision(long id){return ((Number)service.detail(teacherEmail,id,true).get("revision")).intValue();}
    private LibraryPdfStore.Stored upload(String text)throws Exception{return store.upload(new MockMultipartFile("file","material.pdf","application/pdf",pdf(text,false)));}
    private void publish(long id,boolean download,String scope){tx.executeWithoutResult(status->service.edit(teacherEmail,id,input("PUBLISHED",download,scope,List.of(lesson,secondLesson),revision(id))));}
    static byte[] pdf(String text,boolean script)throws Exception{try(var doc=new PDDocument();var output=new ByteArrayOutputStream()){for(int i=0;i<2;i++){var page=new PDPage();doc.addPage(page);try(var content=new PDPageContentStream(doc,page)){content.beginText();content.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),12);content.newLineAtOffset(50,700);content.showText(text);content.endText();}}if(script)doc.getDocumentCatalog().setOpenAction(new PDActionJavaScript("app.alert('test')"));doc.save(output);return output.toByteArray();}}
    @Test void validatedPdfGenerationAndSecurity()throws Exception{var valid=upload("Material de teste com texto selecionavel");assertEquals(2,valid.pages());assertTrue(valid.hasText());assertFalse(valid.tagged());assertTrue(store.text(valid.key()).contains("selecionavel"));assertTrue(Files.exists(store.file(valid.key())));assertThrows(ResponseStatusException.class,()->store.upload(new MockMultipartFile("file","fake.pdf","application/pdf","not a pdf".getBytes())));assertThrows(ResponseStatusException.class,()->store.upload(new MockMultipartFile("file","active.pdf","application/pdf",pdf("Unsafe",true))));ReflectionTestUtils.setField(store,"maxPages",1);assertThrows(ResponseStatusException.class,()->upload("Too many pages"));ReflectionTestUtils.setField(store,"maxPages",300);var generated=store.compose("Módulo de matemática","Frações, proporções e equações.\n"+"Exemplo acessível. ".repeat(80));assertTrue(generated.hasText());assertTrue(store.text(generated.key()).contains("equações"));ReflectionTestUtils.setField(store,"maxBytes",10L);assertThrows(ResponseStatusException.class,()->upload("Oversize"));}
    @Test void publicationScopeSearchAndSharedAssociations()throws Exception{long id=create();assertTrue(service.list(studentEmail,false,course,null,null,null,null,null,null,null).isEmpty());assertThrows(ResponseStatusException.class,()->service.detail(studentEmail,id,false));assertThrows(ResponseStatusException.class,()->publish(id,true,"STUDENTS"));var file=upload("First version");tx.execute(status->service.install(teacherEmail,id,file,revision(id)));publish(id,true,"STUDENTS");assertEquals(1,service.list(studentEmail,false,course,subject,module,lesson,"fraç","Apostila",teacher,null).size());assertEquals(1,service.list(studentEmail,false,course,null,null,secondLesson,null,null,null,null).size());assertTrue(service.list(studentEmail,false,null,null,null,null,"unknown",null,null,null).isEmpty());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM learning_material_versions WHERE material_id=?",Integer.class,id));assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM learning_material_lessons WHERE material_id=?",Integer.class,id));assertEquals(file.key(),service.version(studentEmail,id,null,true).get("storage_key"));}
    @Test void ownershipRestrictedAccessAndWithdrawal()throws Exception{long id=create();var file=upload("Restricted");tx.execute(status->service.install(teacherEmail,id,file,revision(id)));publish(id,false,"STUDENTS");assertThrows(ResponseStatusException.class,()->service.version(studentEmail,id,null,true));assertNotNull(service.version(studentEmail,id,null,false));assertThrows(ResponseStatusException.class,()->service.detail(otherEmail,id,true));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->service.delete(otherEmail,id)));publish(id,true,"TEACHERS");assertThrows(ResponseStatusException.class,()->service.version(studentEmail,id,null,false));assertTrue(service.list(studentEmail,false,course,null,null,null,null,null,null,null).isEmpty());assertNotNull(service.version(teacherEmail,id,null,true));publish(id,true,"STUDENTS");tx.executeWithoutResult(status->service.edit(teacherEmail,id,input("HIDDEN",true,"STUDENTS",List.of(),revision(id))));assertThrows(ResponseStatusException.class,()->service.version(studentEmail,id,null,false));}
    @Test void versionsConcurrencyDeletionAndForeignAssociations()throws Exception{long id=create();var first=upload("First version");tx.execute(status->service.install(teacherEmail,id,first,0));publish(id,true,"STUDENTS");int old=revision(id);var second=upload("Second version");tx.execute(status->service.install(teacherEmail,id,second,old));assertThrows(ResponseStatusException.class,()->service.version(studentEmail,id,null,false));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->service.edit(teacherEmail,id,input("PUBLISHED",true,"STUDENTS",List.of(),old))));publish(id,true,"STUDENTS");var history=(List<?>)service.detail(teacherEmail,id,true).get("versions");assertEquals(2,history.size());long oldVersion=((Number)((Map<?,?>)history.get(1)).get("id")).longValue();assertEquals(first.key(),service.version(teacherEmail,id,oldVersion,false).get("storage_key"));assertThrows(ResponseStatusException.class,()->service.version(studentEmail,id,oldVersion,false));var same=tx.execute(status->service.install(teacherEmail,id,second,revision(id)));assertEquals(true,same.get("duplicate"));assertEquals(2,((List<?>)service.detail(teacherEmail,id,true).get("versions")).size());long foreignCourse=((Number)learning.createCourse(otherEmail,new LearningController.CourseInput("Other","","Other",null,"PUBLISHED")).get("id")).longValue();var invalid=new LibraryService.MaterialInput(foreignCourse,subject,module,"Wrong","","","","","STUDENTS",true,"DRAFT",List.of(lesson),null);assertThrows(ResponseStatusException.class,()->tx.execute(status->service.create(otherEmail,invalid)));tx.executeWithoutResult(status->service.delete(teacherEmail,id));assertThrows(ResponseStatusException.class,()->service.version(teacherEmail,id,null,false));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM learning_library_audit WHERE material_id=? AND event='DELETED'",Integer.class,id));}
    private static String email(){return UUID.randomUUID()+"@example.test";}private static String env(String name,String fallback){String value=System.getenv(name);return value==null||value.isBlank()?fallback:value;}
}
